\documentclass{article}
% Portrait A0: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Dark Tech Color Theme ──
\definecolor{bgdark}{HTML}{0F172A}
\definecolor{bgcard}{HTML}{1E293B}
\definecolor{bgcardalt}{HTML}{162032}
\definecolor{bgcardhi}{HTML}{1A2744}
\definecolor{bgsurface}{HTML}{263348}
\definecolor{primary}{HTML}{3B82F6}
\definecolor{primarylight}{HTML}{60A5FA}
\definecolor{teal}{HTML}{14B8A6}
\definecolor{amber}{HTML}{F59E0B}
\definecolor{coral}{HTML}{F97316}
\definecolor{pink}{HTML}{EC4899}
\definecolor{green}{HTML}{22C55E}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textmuted}{HTML}{94A3B8}
\definecolor{textdim}{HTML}{64748B}
\definecolor{bordersub}{HTML}{334155}
\definecolor{openai}{HTML}{22C55E}
\definecolor{anthropic}{HTML}{F97316}
\definecolor{google}{HTML}{60A5FA}
\definecolor{deepseek}{HTML}{14B8A6}
