\definecolor{tablerow}{HTML}{1A2744}
\definecolor{tablerowalt}{HTML}{162032}
\definecolor{statbox}{HTML}{172240}

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Card styles for dark theme ──
\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0.5pt, colframe=bordersub,
    colback=bgcard,
    left=16pt, right=14pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bgcardalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  tealcard/.style={
    enhanced, arc=4pt, boxrule=0.5pt, colframe=bordersub,
    colback=bgcard,
    left=16pt, right=14pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=bgcardalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={teal!40},
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  ambercard/.style={
    enhanced, arc=4pt, boxrule=0.5pt, colframe=bordersub,
    colback=bgcard,
    left=16pt, right=14pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgcardalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={amber!40},
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colframe=primary!60,
    colback=bgcardhi,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primary!80!black,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.35, color=black},
  },
}

\begin{document}
