  enhanced, colback=bgcardalt, colframe=bgcardalt, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{primary!60},
  left=50pt, right=50pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{30}{36}\selectfont\color{textmuted}\textbf{AIDER BENCHMARK 2025}}\\[10pt]
