% ABOUT THE BENCHMARK
\posterbox[darkcard, title={About the Benchmark}
]{name=about, column=3, span=1, between=row5 and row8}{
  \fontsize{30}{40}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=10pt]
    \item AI pair-programming tool \textbf{Aider} evaluates LLMs on autonomous code editing
    \item \textbf{225 Exercism exercises} across 6 languages: C++, Go, Java, JavaScript, Python, Rust
    \item Models get \textbf{two attempts} per task --- no human help allowed
    \item Primary metric: \textbf{\% exercises passing all tests}
  \end{itemize}
}

% COST vs ACCURACY INSIGHT
\posterbox[ambercard, title={Cost vs.\ Accuracy}
]{name=costinsight, column=3, span=1, between=row8 and row12}{
