    {\fontsize{26}{32}\selectfont\color{textmuted} Gemini 2.5 Flash (\$1.28) vs GPT-5 (\$29.08)}%
    \vspace{6pt}%
  }}

  \vspace{10pt}
  \begin{itemize}[itemsep=10pt]
    \item \textbf{DeepSeek R1}: 80.4\% at \$3.88 --- best value in top 10
    \item \textbf{Gemini 2.5 Pro}: 82.7\% at \$4.92 --- premium accuracy, budget cost
    \item Sub-\$5 models clear \textbf{72\%+} accuracy
    \item Top accuracy demands \textbf{4--7\texttimes{}} the cost of mid-tier options
  \end{itemize}
}

% EDIT FORMAT COMPLIANCE
