    {\fontsize{26}{32}\selectfont\color{textdim} plain diff: 85--92\% correct}%
    \vspace{6pt}%
  }}

  \vspace{10pt}
  \begin{itemize}[itemsep=10pt]
    \item Claude models lead: Opus at \textbf{97.3\%} format compliance
    \item diff-fenced $\Rightarrow$ more reliable automated pipelines
    \item GPT-5 uses plain diff at 88--92\%
  \end{itemize}
}

% ══════════════════════════════════════════════════════════
